#!/usr/bin/env node
/* Auto-generated by the Manga admin panel. Builds a minimal WebView APK project. */
const fs = require('fs');
const path = require('path');

let cfg = {};
try {
  cfg = JSON.parse(fs.readFileSync('apk-config.json', 'utf8'));
} catch {
  cfg = {};
}

const env = process.env;

const nameCandidates = [env.APP_NAME, cfg.app_name, cfg.site_name]
  .map((v) => String(v || '').trim())
  .filter((v) => v && !/^(app|application|android|manga)$/i.test(v));
const rawAppName = nameCandidates[0] || String(cfg.site_name || cfg.app_name || 'Manga').trim();
const appName =
  rawAppName
    .replace(/\s*(Reader|App|Application|Android)\s*$/i, '')
    .replace(/\s*[-_|]\s*(Reader|App|Application)\s*$/i, '')
    .trim() || 'Manga';

let pkg = String(cfg.package_id || env.FALLBACK_PACKAGE || 'com.mangareader.app').trim();
if (!/^[a-zA-Z][a-zA-Z0-9_]*(\.[a-zA-Z][a-zA-Z0-9_]*)+$/.test(pkg)) {
  console.warn('Invalid package_id, falling back to com.mangareader.app');
  pkg = 'com.mangareader.app';
}

const versionName = String(env.VERSION_NAME || cfg.version_name || '1.0.0')
  .replace(/'/g, '')
  .replace(/"/g, '')
  .replace(/[^\w.-]/g, '');
const versionCode = Math.max(1, parseInt(env.VERSION_CODE || cfg.version_code || '1', 10) || 1);
// Standalone APK: never wrap an ephemeral Horizons preview URL — those expire
// with the preview session and leave the installed app on a blank screen. The
// stable production domain serves both the web app and its API at the same
// origin, so every feature keeps working inside the WebView.
const PRODUCTION_DOMAIN = 'https://mangany.site';
function isPreviewUrl(u) {
  const s = String(u || '').toLowerCase();
  return (
    s.includes('app-preview.com') ||
    s.includes('app-preview.') ||
    s.includes('horizons') ||
    !s ||
    /^[a-z0-9]{8}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{12}\./i.test(s) ||
    s.includes('example.com')
  );
}
const rawWebsiteUrl = String(env.WEBSITE_URL || cfg.website_url || '').trim();
const websiteUrl = isPreviewUrl(rawWebsiteUrl) ? PRODUCTION_DOMAIN : rawWebsiteUrl.replace(/\/+$/, '');
let color = String(cfg.primary_color || '#E23636').trim();
if (!/^#([0-9A-Fa-f]{3}|[0-9A-Fa-f]{4}|[0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$/.test(color)) {
  color = '#E23636';
}
if (color.length === 4) {
  color = '#' + color[1] + color[1] + color[2] + color[2] + color[3] + color[3];
}
if (color.length === 9) {
  color = '#' + color.slice(3);
}

const minSdk = Math.max(21, parseInt(cfg.min_sdk || 24, 10) || 24);
const targetSdk = Math.min(34, Math.max(minSdk, parseInt(cfg.target_sdk || 34, 10) || 34));
const compileSdk = 34;

// AGP 8.2.2 + Gradle 8.2 — stable on ubuntu-latest
const AGP_VERSION = '8.2.2';
const GRADLE_VERSION = '8.2';

const writeText = (p, content) => {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  const body = String(content);
  fs.writeFileSync(p, body.endsWith('\n') ? body : body + '\n', 'utf8');
  console.log('wrote', p);
};

const xmlEscape = (s) =>
  String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');

const pkgPath = pkg.split('.').join('/');
const baseUrl = websiteUrl || 'https://example.com';
const appUrl =
  baseUrl +
  (baseUrl.includes('?') ? '&' : '?') +
  'app=1&app_version=' +
  encodeURIComponent(versionName) +
  '&app_code=' +
  versionCode;
const safeUrl = appUrl.replace(/\\/g, '\\\\').replace(/"/g, '\\"');

function writeVectorIcon() {
  writeText(
    'app/src/main/res/drawable/ic_launcher.xml',
    [
      '<?xml version="1.0" encoding="utf-8"?>',
      '<vector xmlns:android="http://schemas.android.com/apk/res/android"',
      '    android:width="108dp"',
      '    android:height="108dp"',
      '    android:viewportWidth="108"',
      '    android:viewportHeight="108">',
      '    <path',
      '        android:fillColor="' + color + '"',
      '        android:pathData="M0,0h108v108h-108z" />',
      '    <path',
      '        android:fillColor="#FFFFFF"',
      '        android:pathData="M30,30h48v48h-48z" />',
      '</vector>',
    ].join('\n'),
  );
}

const MIPMAP_BUCKETS = [
  { dir: 'mipmap-ldpi', size: 36 },
  { dir: 'mipmap-mdpi', size: 48 },
  { dir: 'mipmap-hdpi', size: 72 },
  { dir: 'mipmap-xhdpi', size: 96 },
  { dir: 'mipmap-xxhdpi', size: 144 },
  { dir: 'mipmap-xxxhdpi', size: 192 },
];

function isPngBuffer(buf) {
  return (
    Buffer.isBuffer(buf) &&
    buf.length >= 24 &&
    buf[0] === 0x89 &&
    buf[1] === 0x50 &&
    buf[2] === 0x4e &&
    buf[3] === 0x47 &&
    buf[4] === 0x0d &&
    buf[5] === 0x0a &&
    buf[6] === 0x1a &&
    buf[7] === 0x0a
  );
}

function readPngIhdr(buf) {
  // PNG signature (8) + IHDR length(4) + type(4) + data…
  if (!isPngBuffer(buf)) return null;
  const type = buf.toString('ascii', 12, 16);
  if (type !== 'IHDR') return null;
  const width = buf.readUInt32BE(16);
  const height = buf.readUInt32BE(20);
  const bitDepth = buf[24];
  const colorType = buf[25];
  return { width, height, bitDepth, colorType };
}

/**
 * Decode website logo from apk-icon.b64 and place launcher PNGs in every
 * mipmap density bucket. Falls back to vector drawable on any failure.
 * Returns icon resource ref: '@mipmap/ic_launcher' or '@drawable/ic_launcher'.
 */
function installLauncherIcon() {
  const MAX_BYTES = 2 * 1024 * 1024;
  const MAX_DIM = 2048;

  let pngBuf = null;
  if (fs.existsSync('apk-icon.b64')) {
    try {
      const b64 = fs.readFileSync('apk-icon.b64', 'utf8').replace(/\s+/g, '');
      if (b64.length > 0) {
        pngBuf = Buffer.from(b64, 'base64');
        console.log('apk-icon.b64 decoded to', pngBuf.length, 'bytes');
      }
    } catch (e) {
      console.warn('apk-icon.b64 read/decode failed:', e.message);
      pngBuf = null;
    }
  } else {
    console.log('apk-icon.b64 not found — vector launcher fallback');
  }

  if (!pngBuf || !isPngBuffer(pngBuf)) {
    if (pngBuf) console.warn('apk-icon.b64 is not a valid PNG — vector fallback');
    writeVectorIcon();
    return '@drawable/ic_launcher';
  }

  if (pngBuf.length > MAX_BYTES) {
    console.warn(
      'logo PNG too large (' + pngBuf.length + ' > ' + MAX_BYTES + ') — vector fallback',
    );
    writeVectorIcon();
    return '@drawable/ic_launcher';
  }

  const ihdr = readPngIhdr(pngBuf);
  if (!ihdr || !ihdr.width || !ihdr.height) {
    console.warn('PNG IHDR unreadable — vector fallback');
    writeVectorIcon();
    return '@drawable/ic_launcher';
  }
  if (ihdr.width > MAX_DIM || ihdr.height > MAX_DIM) {
    console.warn(
      'PNG dimensions ' + ihdr.width + 'x' + ihdr.height + ' too large — vector fallback',
    );
    writeVectorIcon();
    return '@drawable/ic_launcher';
  }
  // Reject exotic types that sometimes trip older aapt; allow 2/3/4/6 (gray, RGB, palette, RGBA)
  if (![0, 2, 3, 4, 6].includes(ihdr.colorType)) {
    console.warn('PNG colorType ' + ihdr.colorType + ' unsupported — vector fallback');
    writeVectorIcon();
    return '@drawable/ic_launcher';
  }

  // Same validated PNG in every density bucket. Android scales for the device;
  // avoids needing a native image resizer inside the CI generator.
  for (const bucket of MIPMAP_BUCKETS) {
    const dir = path.join('app/src/main/res', bucket.dir);
    fs.mkdirSync(dir, { recursive: true });
    const out = path.join(dir, 'ic_launcher.png');
    fs.writeFileSync(out, pngBuf);
    // Verify magic still intact after write
    const check = fs.readFileSync(out);
    if (!isPngBuffer(check)) {
      console.warn('mipmap write corrupt at', out, '— vector fallback');
      try {
        fs.rmSync('app/src/main/res/mipmap-ldpi', { recursive: true, force: true });
        fs.rmSync('app/src/main/res/mipmap-mdpi', { recursive: true, force: true });
        fs.rmSync('app/src/main/res/mipmap-hdpi', { recursive: true, force: true });
        fs.rmSync('app/src/main/res/mipmap-xhdpi', { recursive: true, force: true });
        fs.rmSync('app/src/main/res/mipmap-xxhdpi', { recursive: true, force: true });
        fs.rmSync('app/src/main/res/mipmap-xxxhdpi', { recursive: true, force: true });
      } catch {
        /* ignore */
      }
      writeVectorIcon();
      return '@drawable/ic_launcher';
    }
    console.log('wrote', out, '(' + check.length + ' bytes, src ' + ihdr.width + 'x' + ihdr.height + ')');
  }

  // Keep a drawable vector as secondary roundIcon fallback only if needed — not used when mipmap OK.
  console.log(
    'Launcher icon installed from website logo PNG (' +
      ihdr.width +
      'x' +
      ihdr.height +
      ', ' +
      pngBuf.length +
      ' bytes) → @mipmap/ic_launcher',
  );
  return '@mipmap/ic_launcher';
}

